"""Generate every numerical manuscript claim and the empirical report."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(name):return json.loads((ROOT/'tables'/f'{name}.json').read_text())
def f(x,d=3):return f'{x:.{d}f}'
def main():
    rows=read('revision_summary');sol=read('solver_summary');risks=read('scalar_risk_saved');rt=read('runtime_revision');cal=read('calibration')
    def one(case,method,alpha=.05):return next(r for r in rows if r['case']==case and r['method']==method and r['alpha']==alpha)
    p1=[r for r in rows if r['suite']=='V05' and r['method']=='cap_fixed' and r['alpha']==.05]
    old=next(r for r in risks if r['case']=='S03_002');strong=one('V01_009','cap_fixed');weak=one('V01_001','cap_fixed');xch=one('V01_001','xch_known')
    sig=one('V04_000','independent_upper_sigma');naive=one('V04_000','naive_plugin_sigma')
    cert=sum(r['certified'] for r in sol);gap=[r['mean_gap'] for r in sol if r['budget']==3000]
    tex=r'''The revision retains the original 1,084,640 saved Monte Carlo datasets and re-evaluates all 303 interval-producing cases under the corrected numerical and scalar definitions; no new noise is drawn for that reevaluation. It adds 87,200 independently seeded datasets across 55 pre-specified configurations. V01 uses 1,000 paired datasets at each of ten signal levels, V02 uses 50 observations at each of four amplitudes shared across three search budgets, V03 uses 1,000 datasets in each of 19 corruption/noise cases, V04 uses 3,000 in each of 18 variance cases, and V05 uses 1,000 in each of four larger pointwise cases. Tables and figures are generated from raw endpoints and estimates. The empirical supplement contains the full configuration registry, paired differences, failures, Wilson coverage intervals, length standard errors and estimator identities.

Coverage comparisons allow only four representable endpoint steps for rounding, retain strict counts, and have no target-scaled statistical tolerance. Re-evaluation changes two 90\% rows for the same observation: the known-noise XCH and oracle counts in S03\_007 change from 134/150 to 133/150. An exact-noise replay distinguishes that genuine miss from the harmless one-ULP structural-boundary discrepancies. Two power-of-two rescalings per saved interval case preserve the revised events. These numerical checks do not constitute formal interval arithmetic.

\paragraph{Supplied budgets and controlled ablations.}
V01 holds the outer budget fixed while varying the signal, with a paired norm-comparable budget branch. All comparisons use the same observation and pilot. Bias-only removal freezes the original candidate choice; fallback-only removal forces the tangent candidate and retains both intersections; quantile-only removal changes only the validation critical value. A separate no-intersection diagnostic and the historical combined diagnostic are also retained. At weak signals, bias-only removal changes no reported interval because the fallback is selected. Thus the old combined failure cannot be attributed to bias alone. Reducing the validation quantile can lower coverage while preserving the other protections.
'''
    tex+=f'At amplitude two, fixed-budget cap coverage is {f(weak["coverage"])} and the regular XCH comparator has coverage {f(xch["coverage"])}. At the largest amplitude, cap coverage is {f(strong["coverage"])} with mean length {f(strong["length"])}. These are finite-sample observations, not uniform performance guarantees. The norm-comparable sweep answers a different question because its supplied class changes.\n'
    tex+=r'''\begin{figure}[t]\centering
\includegraphics[width=\textwidth]{../figures/02_fixed_budget.pdf}
\caption{Paired fixed-budget and norm-comparable signal sweeps at $p=16$, cap one and $\tau=1$, with 1,000 new datasets per amplitude. The fixed budget is $342023.69$ throughout. Bars are Wilson 95\% coverage intervals or 1.96 standard errors for mean length. XCH is not guaranteed over the weak-signal cap union.}\label{fig:signal}
\end{figure}
\paragraph{Pointwise precision and scalar loss.}
'''
    tex+=f'In the four new $p=32,64$ cases, cap coverage ranges from {f(min(r["coverage"] for r in p1))} to {f(max(r["coverage"] for r in p1))}; normalized mean lengths range from {f(min(r["length_over_pointwise_rate"] for r in p1),2)} to {f(max(r["length_over_pointwise_rate"] for r in p1),2)} times $\\tau\\sqrt{{r/p}}$. This supports the stated finite-grid behavior under deliberately strong P1 conditions, without identifying a limiting slope or optimal signal threshold. Regular XCH and the support oracle have smaller constants here.\n\n'
    tex+=f'The saved S03\\_002 midpoint MSE is {old["midpoint_mse"]:,.3f}, with one sentinel event among 500 draws. The R1 companion on the same observations has MSE {f(old["companion_mse"])} (standard error {f(old["companion_mse_se"])}), below its uniform theoretical bound {f(old["risk_upper"])}. All sentinel observations remain in the loss calculation, and every interval endpoint is unchanged. The old midpoint is retained as a diagnostic, never relabeled as the R1 estimator.\n'
    tex+=r'''\begin{figure}[t]\centering
\includegraphics[width=\textwidth]{../figures/04_scalar_and_pointwise.pdf}
\caption{Strong saturated cases with 1,000 new datasets each. Left: unconditional empirical MSE including rare sentinel losses; the scalar correction leaves confidence intervals unchanged. Right: length divided by $\tau\sqrt{r/p}$, with 1.96 standard errors. The logarithmic MSE display does not assert precise estimation of rare-loss expectations; all raw losses and their uncertainty are retained.}\label{fig:pointwise}
\end{figure}
\paragraph{Calibration and assumption violations.}
'''
    tex+=f'All 18 within-cap whole-replicate corruption cases have median-interval coverage 1.000 in 1,000 trials each, with conservative lengths; the deliberately violated 120-row/zero-supplied-cap case has coverage 0.000. For $m=1,n=2,\\sigma=1$, independent upper-scale calibration has coverage {f(sig["coverage"])} versus {f(naive["coverage"])} for the naive plug-in. Gaussian residual independence and the chi-square degrees of freedom are part of the experiment, not assumed for arbitrary noise. Fourth-moment-based MSE error bars are not asserted for the heavy-tail cases.\n\n'
    tex+=r'''\paragraph{Optimization and input cost.}
'''
    tex+=f'V02 fixes the arbitrary loading, signal direction, norm budget, noise and tolerance across all budgets. Of 600 solves, {cert} meet endpoint tolerance $0.05$, all at the largest budget and strongest amplitude; {600-cert} remain unresolved. Mean gaps at 3,000 nodes range from {f(min(gap))} to {f(max(gap))}. All feasible-witness gaps are finite and retained, including failures. These guarded float64 outer bounds do not implement the ideal high-dimensional minimax estimator. Fresh timings of the revised public scalar/interval interface use one thread, one warmup and ten calls per dimension; $p=64$ requires {rt[-1]["input_bytes"]:,} input bytes and averages {f(rt[-1]["mean_seconds"],4)} seconds per call. Traced allocations exclude the preallocated input and potentially untraced native workspace.\n\n'
    tex+=r'''The XCH comparison is a local implementation of the tensor-PCA procedure in Section 4.2 of \citet{xu2025}: HOSVD initialization and two simultaneous projection updates, with known-noise and residual plug-in scales. Its regular-stratum theorem requires more than correct rank. Zero and rank-mismatched cases are explicitly outside the specified model; initialization, alignment and remainder constants are not certified for the other individual cases. No inference of finite-sample cap-uniform coverage or leading-constant dominance is made from these comparisons.
'''
    (ROOT/'paper/empirical_results.tex').write_text(tex)
    abstract=r'''\begin{abstract}
We study honest confidence intervals for a prescribed linear functional of a Gaussian tensor mean under supplied Tucker or tensor-train rank caps and a Frobenius norm bound. For a normalized flat orthogonal loading and fixed positive caps, we characterize full-data minimax expected length at zero and in the worst case for every positive norm and noise budget, together with the corresponding squared-risk rate. At $M=\tau\sqrt p$, the length scale is $\tau\{\log(ep)\}^{3/2}/\sqrt p$ for order three and $\tau\sqrt{\log(ep)/p}$ for higher orders. Residual scans and full-likelihood mixtures explain the distinction from the diagonal observation experiment. We also delimit matched growing-cap and loading regimes, adaptation obstructions, and efficient strong saturated pointwise inference. A separate scalar companion gives uniform noise-scale risk without changing the intervals. Controlled simulations examine supplied-budget sensitivity, component ablations, scale calibration and computational gaps. General efficient fixed-cap weak-signal computation, arbitrary-loading rates and complete pointwise adaptation remain open.
\end{abstract}
'''
    (ROOT/'paper/abstract.tex').write_text(abstract)
    out=['# Revised empirical analysis','September 13, 2026. Canonical report accompanying the revised main paper and technical supplement.',
         '## Data and dependency accounting',
         'The original study contains 1,084,640 saved datasets in 318 stochastic configurations plus 84 analytic-only configurations. All 303 interval-producing cases were re-evaluated from their original raw draws with the four-ULP policy and R1 scalar estimator. The remaining 15 event-only cases have no affected intervals. This is deterministic method reevaluation, not 1,084,640 new draws. All original files are preserved. The revision adds **87,200 new independent datasets**, 55 configurations, and 600 binary optimizer solves on 200 observations. Three confidence levels reuse observations, and their losses reuse an explicitly identified 95% scalar estimate where relevant; they are not independent datasets.',
         'Case-local seeds use master seed 2026091309, SHA-256 case identifiers, trial and stream. Original saved experiments retain seed 2026091203. Configurations were registered before execution, with no outcome tuning. One thread was used within each independent simulation process; paired procedures share data and pilot randomness. Fixed-M and norm-comparable-M branches are labeled separately. Raw new outputs, the exactly derived pure-fallback ablation, and independently recomputed summaries are kept separately.',
         '## Coverage and scalar corrections',
         'Two corrected 90% rows, both S03_007 (known-noise XCH and support oracle), change from 134/150 to 133/150. They correspond to one genuine Gaussian miss, not two independent failures. Strict coverage and four-ULP coverage are both retained; 24 strict/tolerant discrepancies at exact structural boundaries were previously verified as harmless algebraic rounding. A target-proportional tolerance is no longer used.',
         f'The S03_002 midpoint MSE changes from {old["midpoint_mse"]:,.6f} to {old["companion_mse"]:.6f} for the R1 estimator, on exactly the same 500 observations. Its MSE standard error is {old["companion_mse_se"]:.6f}, and its proved noise-scale bound is {old["risk_upper"]:.6f}. One original sentinel event is retained, along with all old losses. All 303 cases have unchanged interval endpoints. The R1 bound is marked inapplicable when the supplied cap or structural range is violated.',
         '## New experiment design',
         '| Suite | Review issue | Design | New datasets |','|---|---|---|---:|',
         '| V01 | F02, F05, F06 | Fixed M signal sweep; paired norm-comparable M; isolated bias, fallback, intersection and quantile diagnostics; XCH/oracle/direct | 10,000 |',
         '| V02 | F07 | One fixed arbitrary loading and direction; M=3, tau=.5; tolerance .05 at 100/600/3000 nodes | 200 |',
         '| V03 | F08 | 18 valid whole-row corruption/noise cases, one deliberate cap violation; Gaussian, correlated and standardized t3 | 19,000 |',
         '| V04 | F08 | Independent residual chi-square bound; m=1/16/64, n=2/4/16, sigma=1/3; alpha0=.04, delta=.01 | 54,000 |',
         '| V05 | E01, F04 | Four p=32/64 strong saturated cases, fixed and rounded growing caps; 1,000 draws each | 4,000 |',
         '## Findings and interpretation',
         f'**Budget and ablation.** At amplitude two the full fixed-M interval covers {weak["coverage"]:.3f}; XCH covers {xch["coverage"]:.3f}, outside certified regularity conditions. Bias-only removal has no effect over the first eight weak/intermediate signal levels because the original fallback is selected. It cannot explain the combined diagnostic failure. Pure fallback removal, which preserves the intersections, is conservative and longer in those cases. Changing only the validation quantile reduces coverage at several levels. These comparisons isolate different mechanisms; they do not establish that every correction is necessary at every mean.',
         f'**Pointwise behavior.** The four new larger cases have coverage {min(r["coverage"] for r in p1):.3f}–{max(r["coverage"] for r in p1):.3f} and normalized lengths {min(r["length_over_pointwise_rate"] for r in p1):.2f}–{max(r["length_over_pointwise_rate"] for r in p1):.2f}. Amplitudes deliberately satisfy the conservative P1 sufficient bound. Rounded caps and finite dimensions prevent fitting an exact asymptotic exponent from these four points. Earlier slopes and their caveats remain in the corrected archive; no favorable pooling across different regimes is performed.',
         '**Robustness.** Median coverage is 1.000 for every tested within-cap row-contamination case, but interval lengths are conservative. The 120-row/zero-supplied-cap violation has coverage 0.000. The uncorrected mean also fails with correlated coordinates or row corruption. These tests address a coordinate-envelope proposition, not general tensor contamination minimaxity.',
         f'**Unknown variance.** The independent upper bound is conservative across the tested grid. For m=1, n=2, sigma=1, coverage is {sig["coverage"]:.4f} versus {naive["coverage"]:.4f} for the naive plug-in. At larger m, structural intervals often dominate; coverage 1 there does not demonstrate accurate variance estimation or efficient interval length. Calibration-event probabilities and Wilson intervals are separately reported.',
         f'**Computation.** {cert}/600 binary solves meet the common tolerance; {600-cert} remain unresolved. All seven successes are at amplitude 2.5 and budget 3,000. Mean endpoint gaps at that budget range from {min(gap):.4f} to {max(gap):.4f}. All observations and finite witness gaps remain in coverage, width and gap summaries. This numerical search does not settle general weak-signal computation.',
         '## Comparator and uncertainty contracts',
         'XCH is the published tensor-PCA algorithm locally reimplemented from Xu–Chen–Han, Section 4.2, Algorithm 3; the related inference statements are in Section 4.3. HOSVD and two simultaneous updates use the same full observation as the other methods. Known-noise and plug-in variants are both retained. Zero and supplied-rank mismatch cases are outside the specified regular class. Other case-level initialization, loading-alignment and remainder constants are not certified, even if the signal is very large. The support oracle receives true support and is labeled as an information benchmark.',
         'Coverage error bars are Wilson 95% intervals; coverage MCSE and paired coverage-difference SE are also exported. Mean-length and finite-moment loss summaries retain sample standard errors. No normal-theory MSE uncertainty is claimed for the t3 experiment: sample diagnostics are retained separately because fourth-moment arguments for the naive mean fail. Empty intervals, failures and catastrophic losses are never removed. No claim of uniform validity is inferred solely from simulated coverage.',
         '## Figures']
    captions=json.loads((ROOT/'figures/captions.json').read_text())
    for name,caption in captions.items():out.extend([f'![{caption}](figures/{name}.pdf)',caption])
    out.extend(['## Complete 95% coverage and length tables','All methods and confidence levels, including paired differences and estimator identities, are available in tables/revision_summary.csv. The following tables include every configuration at 95% with the principal methods; all controlled variants remain in the machine-readable table.'])
    for suite,methods in [('V01',['direct','cap_fixed','cap_matched','xch_known','split_unprotected']),('V02',['direct','global_100','global_600','global_3000']),('V03',['naive_gaussian','bounded_row_median']),('V04',['known_sigma','independent_upper_sigma','naive_plugin_sigma']),('V05',['direct','cap_fixed','xch_known','oracle'])]:
        out.extend([f'### {suite}','| Case / method | Coverage [Wilson 95%] | Mean length (SE) |','|---|---|---|'])
        for r in rows:
            if r['suite']==suite and r['alpha']==.05 and r['method'] in methods:
                lo,hi=r['coverage_wilson_95'];out.append(f'| {r["case"]} / {r["method"]} | {r["coverage"]:.3f} [{lo:.3f}, {hi:.3f}] | {r["length"]:.3f} ({r["length_se"]:.4f}) |')
    out.extend(['## Optimizer precision','| Case | Nodes | Certified / 50 | Mean gap (SE) | Seconds |','|---|---:|---:|---:|---:|'])
    for r in sol:out.append(f'| {r["case"]} | {r["budget"]} | {r["certified"]} | {r["mean_gap"]:.4f} ({r["gap_se"]:.4f}) | {r["mean_seconds"]:.4f} |')
    out.extend(['## Input and allocation accounting','Fresh timing of the revised public API: one warmup plus ten calls; one BLAS thread. Trace excludes preallocated input and may exclude native workspace, so it is not process peak memory. Coordinate-access bytes describe the separate diagonal method, not the full-tensor method.','| p | Input bytes | Diagonal access bytes | API seconds (SE) | Peak traced call bytes |','|---|---:|---:|---:|---:|'])
    for r in rt:out.append(f'| {r["p"]} | {r["input_bytes"]} | {r["diagonal_access_bytes"]} | {r["mean_seconds"]:.6f} ({r["seconds_se"]:.6f}) | {r["peak_traced_call_bytes"]} |')
    out.extend(['## Real-data scope','No suitable repeated-tensor dataset and prescribed scientific contrast was supplied or established. The independent unit, dependence, known-bound justification and preprocessing would need a separate defensible design. This revision makes no real-data or LLM application claim.','## Reproducibility','Run reproduce.sh from this revision directory to rebuild analysis and documents from preserved/new raw draws. Use --rerun-new to execute the 55 registered configurations again. The original saved simulations are regenerated only by their separately preserved original pipeline; the deterministic correction then applies to all saved observations. Source hashes, environment information and validation logs distinguish generation, reevaluation and prior checks.'])
    (ROOT/'empirical_report.md').write_text('\n\n'.join(out).replace('|\n\n|','|\n|')+'\n')
    print('Generated final abstract, numerical main-paper section and complete empirical report.')

if __name__=='__main__':main()
